def load(oiio, np, path):
    image = oiio.ImageInput.open(path)
    if not image:
        return None
    spec = image.spec()
    px = np.asarray(image.read_image(0, 0, 0, spec.nchannels, oiio.FLOAT)).reshape(spec.height, spec.width, -1)
    image.close()
    if px.shape[2] < 3:  # Af: one channel, splatted
        px = np.repeat(px[..., :1], 3, axis=2)
    return px[..., :3]


def crop(prim, img):
    """The edge strips' first two columns are left out: at the strips'
    start Karma's samples outside the strip still find it (coverage 1 where
    the Gaussian filter gives 0.84, unexplained; elsewhere, e.g. on the
    torus's tile border, Karma loses coverage as Nova does)."""
    return img[:, 2:] if prim == "edges" else img


def blocks(np, img, br, bc):
    h, w, c = img.shape
    return img.reshape(br, h // br, bc, w // bc, c).mean(axis=(1, 3))


def render(args, env, renderer, out, reuse=False):
    os.makedirs(out, exist_ok=True)
    images = {}
    for scene, prim, maps, br, bc in RENDERS:
        images[prim] = {m: os.path.join(out, f"{prim}_{m}.exr") for m in maps}
        if reuse and all(os.path.exists(p) for p in images[prim].values()):
            continue
        proc = run([tool(args, "husk.exe"), "--renderer", renderer, "--headlight", "none", "-s", "/Render/" + prim,
                    os.path.join(args.out, "scenes", scene + ".usda")], env, out)
        check(proc.returncode == 0, f"{renderer}: husk {scene} {prim} exits with 0")
        log = proc.stdout + proc.stderr
        if renderer == "Nova":
            check("arning" not in log, f"{renderer}: {scene} {prim} prints no warnings")
        images[prim] = {m: os.path.join(out, f"{prim}_{m}.exr") for m in maps}
    return images


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--hfs", required=True)
    parser.add_argument("--stage", required=True)
    parser.add_argument("--out", required=True)
    parser.add_argument("--renderers", default="Nova,Nova XPU")
    parser.add_argument("--record", action="store_true")
    parser.add_argument("--reuse", action="store_true", help="with --record: keep existing Karma images")
    args = parser.parse_args()
    os.makedirs(args.out, exist_ok=True)
    os.add_dll_directory(os.path.join(args.hfs, "bin"))
    import numpy as np
    import OpenImageIO as oiio

    np.set_printoptions(precision=5, suppress=True, linewidth=200)
    make_scenes.main_into(os.path.join(args.out, "scenes"))
    env, prefs = isolated_env(args)
    if args.record:
        images = render(args, env, "Karma CPU", os.path.join(args.out, "karma"), reuse=args.reuse)
        print("KARMA = {")
        for scene, prim, maps, br, bc in RENDERS:
            print(f"    {prim!r}: {{")
            for m in maps:
                img = load(oiio, np, images[prim][m])
                b = blocks(np, crop(prim, img), br, bc)
                print(f"        {m!r}: {[[round(float(x), 5) for x in v] for v in b.reshape(-1, 3)]},")
            print("    },")
        print("}")
        shutil.rmtree(prefs, ignore_errors=True)
        return 0

    for renderer in args.renderers.split(","):
        tag = renderer.replace(" ", "_")
        images = render(args, env, renderer, os.path.join(args.out, tag))
        for scene, prim, maps, br, bc in RENDERS:
            for m in maps:
                img = load(oiio, np, images[prim][m])
                check(img is not None, f"{renderer} {prim} {m}: image written")
                if img is None:
                    continue
                nova = blocks(np, crop(prim, img), br, bc).reshape(-1, 3)
                karma = np.asarray(KARMA[prim][m])
                tol = TOL[m] + REL.get(m, 0.0) * np.abs(karma)
                err = np.abs(nova - karma) - tol
                worst = int(np.argmax(err.max(axis=1)))
                check(bool((err <= 0).all()),
                      f"{renderer} {prim} {m}: {len(karma)} blocks within {TOL[m]}"
                      f"{' + %g x' % REL[m] if m in REL else ''} of Karma (worst block {worst}: "
                      f"Nova {nova[worst]}, Karma {karma[worst]})")
        # The image filters: the filtered normal map is the raw one divided
        # by the coverage and remapped to [0, 1] where texels are covered,
        # and filled everywhere else.
        out = os.path.join(args.out, tag)
        proc = run([tool(args, "husk.exe"), "--renderer", renderer, "--headlight", "none", "-s", "/Render/filtered",
                    os.path.join(args.out, "scenes", "filters.usda")], env, out)
        check(proc.returncode == 0, f"{renderer}: husk filters filtered exits with 0")
        raw = load(oiio, np, os.path.join(out, "raw_Nt.exr"))
        af = load(oiio, np, os.path.join(out, "raw_Af.exr"))
        filtered = load(oiio, np, os.path.join(out, "filtered_Nt.exr"))
        if raw is not None and af is not None and filtered is not None:
            a = af[..., :1]
            covered = a[..., 0] > 0
            expected = 0.5 + 0.5 * raw / np.maximum(a, 1e-12)
            # Same samples in both renders (same seed): exact up to half floats.
            diff = float(np.abs(filtered - expected)[covered].max()) if covered.any() else 1.0
            check(diff < 2e-3, f"{renderer} filtered Nt: covered texels = 0.5 + 0.5 raw / Af (max diff {diff:.2g})")
            empty = (~covered) & (np.abs(filtered).max(axis=2) == 0)
            check(not empty.any(), f"{renderer} filtered Nt: every texel filled ({int(empty.sum())} empty)")
    shutil.rmtree(prefs, ignore_errors=True)
    print(f"{len(FAILURES)} failure(s)")
    return 1 if FAILURES else 0


if __name__ == "__main__":
    sys.exit(main())
